type Product={id:number;name:string;category:string;material:string;cost:number;price:number;pixPrice?:number|null;compareAtPrice?:number|null;discountPercent?:number|null;installmentCount?:number|null;stock:number;imageUrl?:string;imageUrls?:string[]}; type Client={id:number;name:string;phone:string;email:string;birthday:string;preferences:string}; type Sale={id:number;date:string;productId:number;clientId:number;amount:number;payment:string;discount:number;quantity?:number;channel?:string}; type Cash={id:number;date:string;type:"Entrada"|"Saída";category:string;description:string;amount:number}; type Promo={id:number;name:string;type:string;value:number;code:string;ends:string;active:boolean;uses:number};
const ago=(n:number)=>{const d=new Date();d.setDate(d.getDate()-n);return d.toISOString().slice(0,10)}; const previousMonthStart=()=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-1);return d.toISOString().slice(0,10)}; const previousMonthEnd=()=>{const d=new Date();d.setDate(1);d.setDate(0);return d.toISOString().slice(0,10)}; const br=(d:string)=>new Date(d+"T12:00:00").toLocaleDateString("pt-BR"); const money=(n:number)=>n.toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const CARD_FEE_BUFFER=0.07; const PIX_DISCOUNT_RATE=0.05;
const suggestedPriceFromMarkup=(cost:any,markup:any)=>{const base=Math.max(0,Number(cost)||0)*(1+Math.max(0,Number(markup)||0)/100);return base/(1-CARD_FEE_BUFFER)};
const suggestedPriceFromMargin=(cost:any,fixed:any,margin:any)=>{const raw=Number(margin??40);const target=Number.isFinite(raw)?Math.max(0,raw)/100:.40;const denominator=1-CARD_FEE_BUFFER-target;if(denominator<=0)return 0;return (Math.max(0,Number(cost)||0)+Math.max(0,Number(fixed)||0))/denominator;}; const initials=(n:string)=>n.split(" ").slice(0,2).map(x=>x[0]).join("").toUpperCase(); const normalizeProductImage=async(file:File)=>{if(!["image/jpeg","image/png","image/webp","image/avif"].includes(file.type))throw new Error("Formato de imagem não permitido");if(file.size>5*1024*1024)throw new Error("Cada imagem deve ter no máximo 5 MB");const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||""));reader.onerror=()=>reject(new Error("Não foi possível ler a imagem"));reader.readAsDataURL(file);});const img=await new Promise<HTMLImageElement>((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error("Não foi possível processar a imagem"));image.src=dataUrl;});const size=1000;const canvas=document.createElement("canvas");canvas.width=size;canvas.height=size;const ctx=canvas.getContext("2d");if(!ctx)throw new Error("Não foi possível preparar a imagem");ctx.fillStyle="#ffffff";ctx.fillRect(0,0,size,size);const padding=70;const scale=Math.min((size-padding*2)/img.width,(size-padding*2)/img.height);const w=Math.max(1,Math.round(img.width*scale));const h=Math.max(1,Math.round(img.height*scale));ctx.drawImage(img,Math.round((size-w)/2),Math.round((size-h)/2),w,h);const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,"image/jpeg",0.9));if(!blob)throw new Error("Não foi possível gerar a imagem padronizada");return new File([blob],file.name.replace(/\.[^.]+$/,"")+".jpg",{type:"image/jpeg"});}; const uploadProductImages=async(ownerId:string,productId:number,files:File[])=>{if(!supabase)throw new Error("Supabase indisponível");if(files.length>5)throw new Error("Cada produto pode ter no máximo 5 fotos");const urls:string[]=[];for(const file of files){const normalized=await normalizeProductImage(file);const objectPath=ownerId+"/"+productId+"-"+Date.now()+"-"+urls.length+".jpg";const {error}=await supabase.storage.from("product-images").upload(objectPath,normalized,{contentType:"image/jpeg",upsert:false});if(error)throw error;urls.push(supabase.storage.from("product-images").getPublicUrl(objectPath).data.publicUrl);}return urls;}; const uploadProductImage=async(ownerId:string,productId:number,file:File)=>{const urls=await uploadProductImages(ownerId,productId,[file]);return urls[0]};
const products0:Product[]=[];
const clients0:Client[]=[];
const sales0:Sale[]=[];
const cash0:Cash[]=[];
const promos0:Promo[]=[];
const uploadStorefrontBanner=async(ownerId:string,file:File)=>{if(!supabase)throw new Error("Supabase indisponível");if(!["image/jpeg","image/png","image/webp","image/avif"].includes(file.type))throw new Error("Formato de imagem não permitido");if(file.size>5*1024*1024)throw new Error("A imagem deve ter no máximo 5 MB");const ext=file.name.split(".").pop()?.toLowerCase()||"jpg";const path=ownerId+"/storefront-"+Date.now()+"."+ext;const {error}=await supabase.storage.from("product-images").upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return supabase.storage.from("product-images").getPublicUrl(path).data.publicUrl};
const removeStorefrontBanner=async(url?:string)=>{if(!supabase||!url)return;if(!url.includes("/storage/v1/object/public/product-images/"))return;const path=decodeURIComponent(url.split("/storage/v1/object/public/product-images/")[1]?.split("?")[0]||"");if(!path)return;const {error}=await supabase.storage.from("product-images").remove([path]);if(error)console.warn("Não foi possível remover o arquivo do banner",error);};
const nav=[['dashboard','Visão geral',LayoutDashboard],['sales','Vendas',ShoppingBag],['cash','Fluxo de caixa',Wallet],['fixedCosts','Custos fixos',CircleDollarSign],['products','Produtos',Package],['clients','Clientes',Users],['promos','Promoções',Percent],['orders','Pedidos online',ShoppingBag],['reports','Relatórios',BarChart3],['team','Equipe',Users],['settings','Configurações',Settings],['manuals','Manuais',BookOpen],['productGuide','Cadastro de produtos',Package]] as const;
const adminPathByPage:Record<string,string>={dashboard:"/gestao",sales:"/gestao/vendas",cash:"/gestao/caixa",fixedCosts:"/gestao/custos-fixos",products:"/gestao/produtos",clients:"/gestao/clientes",promos:"/gestao/promocoes",orders:"/gestao/pedidos",reports:"/gestao/relatorios",team:"/gestao/equipe",settings:"/gestao/configuracoes",manuals:"/gestao/manuais",productGuide:"/gestao/cadastro-produtos",logs:"/gestao/logs"};
